1	# ---------------------------------------------------------------------------------------------------------------------
2	# REQUIRED PARAMETERS
3	# These variables must be set.
4	# ---------------------------------------------------------------------------------------------------------------------
5	
6	variable "chart_version" {
7	  description = "Vector helm chart version pin"
8	  type        = string
9	}
10	
11	variable "image_tag_version" {
12	  description = "Vector image tag"
13	  type        = string
14	}
15	
16	variable "datadog_site" {
17	  description = "Datadog site (e.g. datadoghq.com, us3.datadoghq.com)"
18	  type        = string
19	}
20	
21	variable "datadog_api_key_vault_path" {
22	  description = "Vault path for the Datadog API key, consumed by ExternalSecret"
23	  type        = string
24	}
25	
26	variable "external_secrets_cluster_store_name" {
27	  description = "Name of the ClusterSecretStore created by external-secrets module"
28	  type        = string
29	}
30	
31	# ---------------------------------------------------------------------------------------------------------------------
32	# OPTIONAL PARAMETERS
33	# These variables are configurable, but have reasonable defaults set.
34	# ---------------------------------------------------------------------------------------------------------------------
35	
36	variable "image" {
37	  description = "Vector image source"
38	  type        = string
39	  default     = "registry.ic-ops.net/cache-docker-hub/timberio/vector"
40	}
41	
42	variable "replicas" {
43	  description = "Number of Vector aggregator replicas"
44	  type        = number
45	  default     = 3
46	}
47	
48	variable "audit_drop_patterns" {
49	  description = "Regex patterns; matching log message bodies are dropped"
50	  type        = list(string)
51	  default = [
52	    "Audit\\s-\\s.+",
53	    "\"level\":\"audit\"",
54	  ]
55	}
56	
57	variable "email_redaction_enabled" {
58	  description = "Toggle the email-redact VRL transform across all signals"
59	  type        = bool
60	  default     = true
61	}
62	
63	variable "email_redaction_replacement" {
64	  description = "String that replaces matched email addresses"
65	  type        = string
66	  default     = "[REDACTED-EMAIL]"
67	}
68	
69	variable "additional_config" {
70	  description = "Escape hatch — overwrites helm customConfig wholesale (mirrors otel_collector_additional_config semantics)"
71	  type        = any
72	  default     = null
73	}
74	
75	variable "resources_requests" {
76	  description = "Pod resource requests"
77	  type        = map(string)
78	  default = {
79	    cpu    = "200m"
80	    memory = "256Mi"
81	  }
82	}
83	
84	variable "resources_limits" {
85	  description = "Pod resource limits"
86	  type        = map(string)
87	  default = {
88	    cpu    = "2"
89	    memory = "1Gi"
90	  }
91	}
92	
93	variable "namespace" {
94	  description = "Kubernetes namespace for Vector"
95	  type        = string
96	  default     = "vector"
97	}
98	
99	variable "service_monitor_enabled" {
100	  description = "Create a ServiceMonitor for Vector self-metrics. Requires kube-prometheus-stack CRDs in cluster."
101	  type        = bool
102	  default     = false
103	}
