1	role: Aggregator
2	replicas: ${replicas}
3	podAnnotations:
4	  reloader.stakater.com/auto: "true"
5	service:
6	  enabled: true
7	  type: ClusterIP
8	  ports:
9	    - name: otlp-grpc
10	      port: 4317
11	      protocol: TCP
12	    - name: otlp-http
13	      port: 4318
14	      protocol: TCP
15	env:
16	  - name: DATADOG_API_KEY
17	    valueFrom:
18	      secretKeyRef:
19	        name: vector-datadog
20	        key: api_key
21	resources:
22	  requests:
23	    cpu: ${requests_cpu}
24	    memory: ${requests_memory}
25	  limits:
26	    cpu: "${limits_cpu}"
27	    memory: ${limits_memory}
28	podDisruptionBudget:
29	  enabled: true
30	  minAvailable: 2
31	
32	topologySpreadConstraints:
33	  - maxSkew: 1
34	    topologyKey: topology.kubernetes.io/zone
35	    whenUnsatisfiable: ScheduleAnyway
36	    labelSelector:
37	      matchLabels:
38	        app.kubernetes.io/name: vector
39	
40	affinity:
41	  podAntiAffinity:
42	    preferredDuringSchedulingIgnoredDuringExecution:
43	      - weight: 100
44	        podAffinityTerm:
45	          topologyKey: kubernetes.io/hostname
46	          labelSelector:
47	            matchLabels:
48	              app.kubernetes.io/name: vector
49	
50	%{ if service_monitor_enabled ~}
51	serviceMonitor:
52	  enabled: true
53	%{ endif ~}
54	customConfig:
55	  data_dir: /vector-data-dir
56	  api:
57	    enabled: true
58	    address: 127.0.0.1:8686
59	  sources:
60	    otlp_in:
61	      type: opentelemetry
62	      grpc:
63	        address: 0.0.0.0:4317
64	      http:
65	        address: 0.0.0.0:4318
66	  transforms:
67	    drop_audit:
68	      type: filter
69	      inputs:
70	        - otlp_in.logs
71	      condition: |
72	        msg = if is_string(.message) { string!(.message) } else { "" }
73	        ${audit_drop_condition}
74	%{ if email_redaction_enabled ~}
75	    redact_emails_logs:
76	      type: remap
77	      inputs:
78	        - drop_audit
79	      source: |
80	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
81	        if is_string(.message) {
82	          .message = replace(string!(.message), email_re, "${email_redaction_replacement}")
83	        }
84	        if is_object(.attributes) {
85	          attrs, _err = object(.attributes)
86	          if is_object(attrs) {
87	            .attributes = map_values(object!(attrs)) -> |v| {
88	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
89	            }
90	          }
91	        }
92	    redact_emails_traces:
93	      type: remap
94	      inputs:
95	        - otlp_in.traces
96	      source: |
97	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
98	        if is_object(.attributes) {
99	          attrs, _err = object(.attributes)
100	          if is_object(attrs) {
101	            .attributes = map_values(object!(attrs)) -> |v| {
102	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
103	            }
104	          }
105	        }
106	        if is_object(.resource) {
107	          res, _err = object(.resource)
108	          if is_object(res) && is_object(res.attributes) {
109	            rattrs, _err2 = object(res.attributes)
110	            if is_object(rattrs) {
111	              .resource.attributes = map_values(object!(rattrs)) -> |v| {
112	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
113	              }
114	            }
115	          }
116	        }
117	    redact_emails_metrics:
118	      type: remap
119	      inputs:
120	        - otlp_in.metrics
121	      source: |
122	        email_re = r'[\w._%+\-]+@[\w.-]+\.[A-Za-z]{2,}'
123	        if is_object(.attributes) {
124	          attrs, _err = object(.attributes)
125	          if is_object(attrs) {
126	            .attributes = map_values(object!(attrs)) -> |v| {
127	              if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
128	            }
129	          }
130	        }
131	        if is_object(.resource) {
132	          res, _err = object(.resource)
133	          if is_object(res) && is_object(res.attributes) {
134	            rattrs, _err2 = object(res.attributes)
135	            if is_object(rattrs) {
136	              .resource.attributes = map_values(object!(rattrs)) -> |v| {
137	                if is_string(v) { replace(string!(v), email_re, "${email_redaction_replacement}") } else { v }
138	              }
139	            }
140	          }
141	        }
142	%{ endif ~}
143	  sinks:
144	    datadog_logs:
145	      type: datadog_logs
146	      inputs:
147	        - ${email_redaction_enabled ? "redact_emails_logs" : "drop_audit"}
148	      default_api_key: $${DATADOG_API_KEY}
149	      site: ${datadog_site}
150	    datadog_traces:
151	      type: datadog_traces
152	      inputs:
153	        - ${email_redaction_enabled ? "redact_emails_traces" : "otlp_in.traces"}
154	      default_api_key: $${DATADOG_API_KEY}
155	      site: ${datadog_site}
156	    datadog_metrics:
157	      type: datadog_metrics
158	      inputs:
159	        - ${email_redaction_enabled ? "redact_emails_metrics" : "otlp_in.metrics"}
160	      default_api_key: $${DATADOG_API_KEY}
161	      site: ${datadog_site}
